#ifndef DSTAR_DEMODULATOR_H
#define DSTAR_DEMODULATOR_H

#ifndef __cplusplus
#error This header is C++ only!
#endif

#include <cstddef>
#include <cstdint>
#include <memory>
#include "core/audio_path.h"
#include "core/audio_stream.h"
#include "protocols/DSTAR/Constants.hpp"

namespace DStar
{

/**
 * Event generated by the D-STAR receiver.
 */
struct Event {
    enum Type : uint8_t {
        HEADER, ///< Radio header received, see headerValid and header
        FRAME,  ///< Voice frame received, see frame and frameIndex
        END,    ///< End of transmission
        LOST    ///< Synchronisation lost, no data sync for too long
    } type;

    /// HEADER only: the header CRC is valid. The receiver emits valid
    /// headers only, a header failing the CRC is silently dropped.
    bool headerValid;

    /// HEADER only: decoded radio header, CRC included
    uint8_t header[HEADER_SIZE];

    /// FRAME only: AMBE data and slow data, first received bit in the least
    /// significant bit of frame[0]. On frames carrying a detected data sync
    /// (frameIndex 0), the slow data bytes are set to DATA_SYNC.
    uint8_t frame[FRAME_SIZE];

    /// FRAME only: position in the superframe, 0 to 20, 0 being the frame
    /// carrying the data sync
    int8_t frameIndex;
};

/**
 * D-STAR GMSK receiver, a port of MMDVM's D-STAR receive chain (IO.cpp DC
 * removal and Gaussian filter, DStarRX.cpp synchronisation and framing).
 * It has no dependency on the audio subsystem.
 *
 * Input: baseband (FM discriminator) samples at 24 kHz, 5 per symbol. A
 * negative sample is a bit 1 (see invertPhase()). Decisions are taken on
 * the sign of the samples, the amplitude is irrelevant.
 *
 * Memory: about 1.4 kB, all statically sized members (the largest being the
 * 480 samples, one voice frame, of the sample history).
 */
class Receiver
{
public:
    /// Input sample rate, in Hz
    static constexpr uint32_t SAMPLE_RATE = 24000;

    /// Input samples per symbol
    static constexpr size_t SAMPLES_PER_SYMBOL = SAMPLE_RATE / SYMBOL_RATE;

    /// Voice frames without data sync before the synchronisation is lost
    static constexpr size_t MAX_FRAMES = 150;

    /// Capacity of the event queue
    static constexpr size_t EVENT_QUEUE_SIZE = 4;

    /**
     * Constructor.
     */
    Receiver();

    /**
     * \brief Reset the receiver state, pending events included. The phase
     * inversion setting is kept.
     */
    void reset();

    /**
     * \brief Invert the phase of the input signal.
     *
     * @param invert: if true, the input signal phase is inverted.
     */
    void invertPhase(bool invert);

    /**
     * \brief Process a block of baseband samples.
     *
     * When more than EVENT_QUEUE_SIZE events are pending, the oldest ones are
     * dropped: call popEvent() often enough (at least once every 1500
     * samples).
     *
     * @param samples: baseband samples, 24 kHz.
     * @param count: number of samples.
     */
    void process(const int16_t *samples, size_t count);

    /**
     * \brief Get the oldest pending event.
     *
     * @param ev: event, written only if one is pending.
     * @return true if an event has been returned.
     */
    bool popEvent(Event &ev);

    /**
     * \brief Check for pending events.
     *
     * @return true if at least one event is pending.
     */
    bool hasEvents() const;

    /**
     * \brief Check if the receiver is locked on a transmission.
     *
     * @return true between the reception of a valid header or of a data
     * sync and the following end of transmission or loss of synchronisation.
     */
    bool isLocked() const;

private:
    /// Receiver state
    enum class State : uint8_t {
        NONE,   ///< Looking for frame sync or data sync
        HEADER, ///< Receiving the radio header
        DATA    ///< Receiving voice frames
    };

    /// Samples of a voice frame, length of the sample history
    static constexpr size_t FRAME_SAMPLES = FRAME_BITS * SAMPLES_PER_SYMBOL;

    /// Length of the sync patterns compared by the correlators, in bits
    static constexpr size_t SYNC_BITS = 24;

    /// Taps of the receive Gaussian filter
    static constexpr size_t FILTER_TAPS = 11;

    /**
     * Remove the DC offset and apply the receive filter.
     *
     * @param raw: input sample.
     * @return filtered sample.
     */
    int16_t filter(int16_t raw);

    /**
     * Handlers of the states, called for each sample after it has been
     * stored in the history.
     *
     * @param sample: filtered sample.
     */
    void processNone(int16_t sample);
    void processHeader(int16_t sample);
    void processData();

    /**
     * Store the sample in the header bits when it is a header bit sampling
     * point, then advance the header sample counter.
     *
     * @param sample: filtered sample.
     */
    void storeHeaderSample(int16_t sample);

    /**
     * Fuzzy matching of the frame sync, keeping the best correlating phase.
     *
     * @return true if a frame sync better than the previous one was found.
     */
    bool correlateFrameSync();

    /**
     * Fuzzy matching of the data sync, keeping the best correlating phase
     * and setting the frame sampling pointers.
     *
     * @return true if a data sync better than the previous one was found.
     */
    bool correlateDataSync();

    /**
     * Correlate the last SYNC_BITS symbols of the sample history, at the
     * current sampling phase, with a sync pattern.
     *
     * @param pattern: SYNC_BITS bits, oldest in the most significant bit.
     * @return correlation value.
     */
    int32_t correlate(uint32_t pattern) const;

    /**
     * Go back to sync search, after end or loss of a transmission.
     */
    void toNone();

    /**
     * Append an event to the queue, dropping the oldest when it is full.
     *
     * @param ev: event to be queued.
     */
    void pushEvent(const Event &ev);

    State state;                       ///< Current state
    bool inverted;                     ///< Input phase inversion
    bool locked;                       ///< Locked on a transmission
    uint8_t bitPtr;                    ///< Current sampling phase, 0 to 4
    uint8_t countdown;                 ///< Frame sync refinement samples left
    uint16_t dataPtr;                  ///< Current position in dataBuffer
    uint16_t headerPtr;                ///< Samples since the frame sync
    uint16_t startPtr;                 ///< First sample of the next frame
    uint16_t syncPtr;                  ///< Expected end of the next data sync
    uint16_t minSyncPtr;               ///< Data sync search window start
    uint16_t maxSyncPtr;               ///< Data sync search window end
    uint16_t frameCount;               ///< Frames since the last data sync
    int32_t maxFrameCorr;              ///< Best frame sync correlation
    int32_t maxDataCorr;               ///< Best data sync correlation
    float dcLevel;                     ///< DC level estimate
    float dcPrevIn;                    ///< Previous input of the DC estimator
    uint8_t filterPtr;                 ///< Position in filterBuffer
    int16_t filterBuffer[FILTER_TAPS]; ///< Receive filter history

    /// Received bits, one register per sampling phase, newest bit in the
    /// least significant position
    uint64_t bitBuffer[SAMPLES_PER_SYMBOL];

    /// Sample history, one voice frame long
    int16_t dataBuffer[FRAME_SAMPLES];

    /// Header bits, in transmission order
    uint8_t headerBits[HEADER_FEC_SIZE];

    Event events[EVENT_QUEUE_SIZE]; ///< Event queue
    uint8_t eventHead;              ///< Oldest event in the queue
    uint8_t eventCount;             ///< Events in the queue
};

/**
 * Demodulator device for the D-STAR protocol: acquisition of the baseband
 * signal from the RTX and decoding through a Receiver.
 */
class Demodulator
{
public:
    /**
     * Constructor.
     */
    Demodulator();

    /**
     * Destructor.
     */
    ~Demodulator();

    /**
     * \brief Allocate the baseband buffer and the receiver, and initialise
     * the demodulator.
     */
    void init();

    /**
     * \brief Shut down the demodulator and deallocate its memory.
     */
    void terminate();

    /**
     * \brief Start the sampling of the baseband signal in a double buffer.
     */
    void startBasebandSampling();

    /**
     * \brief Stop the sampling of the baseband signal.
     */
    void stopBasebandSampling();

    /**
     * \brief Process the baseband samples acquired since the last call.
     * Blocks until a new half of the baseband buffer is available.
     *
     * @param invertPhase: invert the phase of the baseband signal.
     * @return true if events are pending.
     */
    bool update(bool invertPhase = false);

    /**
     * \brief Get the oldest pending event.
     *
     * @param ev: event, written only if one is pending.
     * @return true if an event has been returned.
     */
    bool popEvent(Event &ev);

    /**
     * \brief Check if the demodulator is locked on a transmission.
     *
     * @return true between the reception of a valid header or of a data
     * sync and the following end of transmission or loss of synchronisation.
     */
    bool isLocked() const;

private:
    /// Samples of half the baseband buffer: 20 ms, one voice frame
    static constexpr size_t SAMPLE_BUF_SIZE = FRAME_BITS
                                            * Receiver::SAMPLES_PER_SYMBOL;

    std::unique_ptr<int16_t[]> basebandBuffer; ///< Baseband double buffer
    std::unique_ptr<Receiver> receiver;        ///< Receiver
    streamId basebandId;                       ///< Baseband input stream
    pathId basebandPath;                       ///< Baseband input path
};

} // namespace DStar

#endif // DSTAR_DEMODULATOR_H
